//! The compiler realm table, generated by build.rs from the runtime's own
//! `#[realm(..)]` declarations: one table, read by codegen and wpfacts.
//!
//! A leaf crate on purpose: every runtime source edit regenerates the table,
//! and only the crates that read it (codegen, wpfacts and their dependents)
//! rebuild; perry-hir and the rest of the front end do not.
use perry_hir::realm_manifest;

include!(concat!(env!("OUT_DIR"), "/realm_table.rs"));
